/**
 * Schema for the smart_execute tool — LLM-powered code generation + sandbox execution.
 */
export const smartExecuteSchema = {
    name: 'smart_execute',
    description: `Describe what you want to create or modify in Figma, and an LLM generates and executes the code for you.

Use this when you know WHAT you want but don't want to write the figma.* code yourself. The tool:
1. Sends your description to an LLM to generate sandbox code
2. Executes the generated code in the figma.* sandbox
3. On error, automatically retries once with error context

This is a single-step tool. For multi-step designs, use design_agent instead.

Requires \`claude\` or \`codex\` CLI installed and available on PATH.

## Examples
- "Create a blue rectangle 200x100 at position (50, 50)"
- "Create a card component with a title, subtitle, and a primary button"
- "Find all text nodes on the current page and change their font to Inter"`,
    inputSchema: {
        type: 'object',
        properties: {
            description: {
                type: 'string',
                description: 'Natural language description of what to create or modify in Figma.',
            },
        },
        required: ['description'],
    },
};
